const landing={patient:'/patient',receptionist:'/reception',doctor:'/doctor',lab_technician:'/lab',pharmacist:'/pharmacy',cashier:'/cashier',admin:'/admin'};
const ok=(v)=>Number.isSafeInteger(Number(v))&&Number(v)>0;
const validDate=(v)=>{if(!/^\d{4}-\d{2}-\d{2}$/.test(String(v||'')))return false;const [y,m,d]=String(v).split('-').map(Number),x=new Date(Date.UTC(y,m-1,d));return x.getUTCFullYear()===y&&x.getUTCMonth()===m-1&&x.getUTCDate()===d;};
const validTime=(v)=>/^(?:[01]\d|2[0-3]):[0-5]\d(?::[0-5]\d)?$/.test(String(v||''));
const toTime=(v)=>String(v).length===5?`${v}:00`:String(v);
const escapeLike=(v)=>String(v||'').replace(/[\\%_]/g,'\\$&');
