function page(req,res,data){const content=pageContent[req.path];res.render('workspace',{...data,title:pageTitles[req.path]||data.title,...(content?{forms:(data.forms||[]).filter(x=>content.forms.includes(x.title)),tables:(data.tables||[]).filter(x=>content.tables.includes(x.title))}:{}),shortcuts:req.user.role==='admin'&&req.path==='/admin'?adminShortcuts:[],nav:workspaceNav[req.user.role]||data.nav,user:req.user,notice:req.query.notice||null,requestPath:req.path,csrfToken:req.csrfToken});}
function get(path,role,fn){router.get(path,auth,roles(role),(req,res,next)=>Promise.resolve(fn(req,res)).catch(next));}
function post(path,role,base,fn){router.post(path,auth,roles(role),(req,res,next)=>Promise.resolve(fn(req,res)).then(note=>res.redirect(`${base}?notice=${encodeURIComponent(note||'Saved.')}`)).catch(e=>{console.error(e);if(e.status&&e.status<500)return res.redirect(`${base}?notice=${encodeURIComponent(e.message)}`);next(e);}));}
function problem(message,status=400){throw Object.assign(new Error(message),{status});}
async function patientFor(userId,executor=db){const [[p]]=await executor.execute('SELECT * FROM patients WHERE user_id=?',[userId]);return p;}
async function assertSlot(executor,doctorId,date,time){
  if(!ok(doctorId)||!validDate(date)||!validTime(time))problem('Choose a valid doctor, date, and time.');
  const [[today]]=await executor.execute("SELECT DATE_FORMAT(CURRENT_DATE,'%Y-%m-%d') today");
  if(date<today.today)problem('Appointments cannot be booked in the past.');
  const weekday=new Date(`${date}T12:00:00`).getDay();
  const [[schedule]]=await executor.execute("SELECT s.start_time,s.end_time,s.slot_minutes FROM doctor_schedules s JOIN users u ON u.id=s.doctor_id WHERE s.doctor_id=? AND s.weekday=? AND u.role='doctor' AND u.status='active'",[doctorId,weekday]);
  if(!schedule)problem('That doctor is not scheduled on this day.',409);
  if(engine.slots(String(schedule.start_time),String(schedule.end_time),schedule.slot_minutes).includes(toTime(time))===false)problem('Choose an available appointment slot.',409);
  const [[off]]=await executor.execute('SELECT id FROM doctor_time_off WHERE doctor_id=? AND off_date=?',[doctorId,date]);
  if(off)problem('That doctor is unavailable on the selected date.',409);
}
function field(name,label,type='text',required=true,options=null,extra={}){return {name,label,type,required,options,...extra};}
const columnFields={'ID':['id','item_id'],'Email':['email'],'Role':['role'],'Status':['status'],'Created':['created_at'],'Hospital no.':['patient_no'],'Name':['name'],'Sex':['sex'],'Birth date':['date_of_birth'],'Phone':['phone'],'Date':['date','appt_date','visit_date','off_date','expires_on','created_at'],'Time':['slot_time'],'Doctor':['doctor'],'Action':['action'],'Visit summary':['complaint'],'Diagnosis':['diagnosis','name'],'Plan':['plan'],'Visit':['id'],'Patient':['patient'],'Test':['test','name'],'Result':['result'],'Flag':['flag'],'Released':['released_at'],'Request':['id'],'Priority':['priority'],'Requested':['requested_at'],'Type':['type'],'Prescription':['prescription_id'],'Drug':['drug'],'Dose':['dose'],'Directions':['directions'],'Qty':['quantity'],'Dispensed':['dispensed'],'Remaining':['remaining'],'Batch':['batch_no'],'Expires':['expires_on'],'Quantity':['qty_remaining'],'Invoice':['invoice_no'],'Total':['total'],'Paid':['paid'],'Balance':['balance'],'Sample':['sample_type'],'Price':['price','unit_price'],'Active':['active'],'Generic':['generic_name'],'Form':['form'],'Strength':['strength'],'Reorder':['reorder_level'],'Code':['code'],'Service':['name'],'Value':['value'],'User':['email'],'Entity':['entity'],'Entity ID':['entity_id'],'Detail':['detail'],'Day':['day'],'Start':['start'],'End':['end'],'Slot minutes':['slot_minutes'],'Fee':['consultation_fee']};
function table(title,columns,rows){return {title,columns:columns.map(label=>{const candidates=columnFields[label]||[label.toLowerCase().replaceAll(' ','_')];return [label,candidates.find(key=>rows.some(row=>key in row))||candidates[0]];}),rows};}

get(['/patient','/patient/appointments','/patient/records'],'patient',async(req,res)=>{
  const p=await patientFor(req.user.id);if(!p)return res.status(404).render('public/error',{message:'Patient profile is not set up. Ask reception to link your account.'});
  const [doctors]=await db.execute("SELECT u.id,CONCAT(s.first_name,' ',s.last_name) name FROM users u JOIN staff_profiles s ON s.user_id=u.id JOIN doctor_schedules ds ON ds.doctor_id=u.id WHERE u.role='doctor' AND u.status='active' GROUP BY u.id ORDER BY name");
  const [appointments]=await db.execute("SELECT a.id,a.appt_date,a.slot_time,a.status,CONCAT(s.first_name,' ',s.last_name) doctor FROM appointments a JOIN users u ON u.id=a.doctor_id JOIN staff_profiles s ON s.user_id=u.id WHERE a.patient_id=? ORDER BY a.appt_date DESC,a.slot_time DESC LIMIT 40",[p.id]);
  const [visits]=await db.execute("SELECT v.id,v.visit_date,c.chief_complaint_enc,c.diagnosis_note_enc,c.treatment_plan_enc,c.status FROM visits v LEFT JOIN consultations c ON c.visit_id=v.id WHERE v.patient_id=? AND (c.status='finalized' OR c.status IS NULL) ORDER BY v.visit_date DESC LIMIT 30",[p.id]);
  const [labs]=await db.execute("SELECT r.id,t.name,r.result_value,r.result_text_enc,r.flag,r.released_at FROM lab_requests r JOIN visits v ON v.id=r.visit_id JOIN lab_tests t ON t.id=r.test_id WHERE v.patient_id=? AND r.status='released' ORDER BY r.released_at DESC LIMIT 20",[p.id]);
  const history=visits.map(v=>({date:v.visit_date,complaint:crypto.decrypt(v.chief_complaint_enc),diagnosis:crypto.decrypt(v.diagnosis_note_enc),plan:crypto.decrypt(v.treatment_plan_enc),status:v.status||'Visit'}));
  const results=labs.map(x=>({test:x.name,result:x.result_value??crypto.decrypt(x.result_text_enc),flag:x.flag||'—',date:x.released_at}));
  const [future]=await db.execute("SELECT COUNT(*) count FROM appointments WHERE patient_id=? AND appt_date>=CURRENT_DATE AND status IN('booked','checked_in','in_consultation')",[p.id]);
  page(req,res,{title:'Patient portal',intro:`Welcome, ${p.first_name}. Manage appointments and review information shared by your care team.`,stats:[['Hospital number',p.patient_no],['Upcoming appointments',future[0].count],['Visits on file',visits.length]],nav:[['/patient','Overview'],['/about','About']],forms:[{title:'Book an appointment',action:'/patient/appointments',submit:'Find and book appointment',fields:[field('doctorId','Doctor','select',true,doctors.map(d=>[d.id,d.name])),field('date','Date','date'),field('time','Time (24 hour)','time'),field('reason','Reason for visit','text',false)]}],tables:[table('Your appointments',['Date','Time','Doctor','Status','Action'],appointments.map(a=>({...a,action:a.status==='booked'?{label:'Cancel',url:`/patient/appointments/${a.id}/cancel`}:null}))),table('Visit summaries',['Date','Visit summary','Diagnosis','Plan','Status'],history),table('Released lab results',['Test','Result','Flag','Released'],results)]});
});
post('/patient/appointments','patient','/patient/appointments',async(req,res)=>{const p=await patientFor(req.user.id);if(!p)problem('Patient profile is not set up.',404);const {doctorId,date,time,reason}=req.body;await assertSlot(db,doctorId,date,time);try{await db.execute("INSERT INTO appointments(patient_id,doctor_id,appt_date,slot_time,status,type,reason) VALUES(?,?,?,?,'booked','online_booking',?)",[p.id,Number(doctorId),date,toTime(time),String(reason||'').slice(0,255)||null]);}catch(e){if(e.code==='ER_DUP_ENTRY')problem('That slot was just booked. Please choose another.',409);throw e;}await audit(req,'create','appointment',null,`patient=${p.id}`);return 'Appointment booked.';});
post('/patient/appointments/:id/cancel','patient','/patient/appointments',async(req,res)=>{if(!ok(req.params.id))problem('Invalid appointment.');const p=await patientFor(req.user.id);const [result]=await db.execute("UPDATE appointments SET status='cancelled',cancelled_at=NOW(),cancel_reason='Cancelled by patient' WHERE id=? AND patient_id=? AND status='booked' AND appt_date>=CURRENT_DATE",[req.params.id,p?.id]);if(!result.affectedRows)problem('This appointment cannot be cancelled.',409);await audit(req,'cancel','appointment',req.params.id);return 'Appointment cancelled.';});

get(['/reception','/reception/patients','/reception/appointments'],'receptionist',async(req,res)=>{
  const [patients]=await db.execute('SELECT id,patient_no,first_name,last_name,sex,date_of_birth,phone,email,status FROM patients ORDER BY id DESC LIMIT 100');
  const [doctors]=await db.execute("SELECT u.id,CONCAT(s.first_name,' ',s.last_name) name FROM users u JOIN staff_profiles s ON s.user_id=u.id WHERE u.role='doctor' AND u.status='active' ORDER BY name");
  const [patientOptions]=await db.execute("SELECT id,CONCAT(patient_no,' — ',first_name,' ',last_name) name FROM patients WHERE status='active' ORDER BY first_name,last_name");
  const [appointments]=await db.execute("SELECT a.id,a.appt_date,a.slot_time,a.status,a.type,p.patient_no,CONCAT(p.first_name,' ',p.last_name) patient,CONCAT(s.first_name,' ',s.last_name) doctor FROM appointments a JOIN patients p ON p.id=a.patient_id JOIN staff_profiles s ON s.user_id=a.doctor_id WHERE a.appt_date>=CURRENT_DATE ORDER BY a.appt_date,a.slot_time LIMIT 100");
  page(req,res,{title:'Registration desk',intro:'Register patients, arrange visits, and check patients into the queue.',stats:[['Patient records',patients.length],['Upcoming appointments',appointments.length],['Active doctors',doctors.length]],nav:[['/reception','Overview'],['/about','About']],forms:[{title:'Register a patient',action:'/reception/patients',submit:'Register patient',fields:[field('firstName','First name'),field('lastName','Last name'),field('sex','Sex','select',true,[['female','Female'],['male','Male'],['other','Other'],['undisclosed','Prefer not to say']]),field('dateOfBirth','Date of birth','date'),field('phone','Phone'),field('email','Email (optional)','email',false),field('createLogin','Create portal login (initial password: password123)','checkbox',false,null,{value:'yes'})]},{title:'Book a patient appointment',action:'/reception/appointments',submit:'Book appointment',fields:[field('patientId','Patient','select',true,patientOptions.map(p=>[p.id,p.name])),field('doctorId','Doctor','select',true,doctors.map(d=>[d.id,d.name])),field('date','Date','date'),field('time','Time (24 hour)','time'),field('reason','Reason','text',false)]}],tables:[table('Patients',['Hospital no.','Name','Sex','Birth date','Phone','Email','Status'],patients.map(p=>({...p,name:`${p.first_name} ${p.last_name}`}))),table('Appointment queue',['Date','Time','Hospital no.','Patient','Doctor','Type','Status','Action'],appointments.map(a=>({...a,action:a.status==='booked'?{label:'Check in',url:`/reception/appointments/${a.id}/check-in`}:null}))) ]});
});
post('/reception/patients','receptionist','/reception/patients',async(req,res)=>{const {firstName,lastName,sex,dateOfBirth,phone,email,createLogin}=req.body;if(!firstName?.trim()||!lastName?.trim()||!['female','male','other','undisclosed'].includes(sex)||!validDate(dateOfBirth)||dateOfBirth>new Date().toISOString().slice(0,10)||!phone?.trim()||(createLogin==='yes'&&!String(email||'').trim()))problem('Enter the patient name, sex, valid birth date, and phone.');const conn=await db.getConnection();try{await conn.beginTransaction();let userId=null;const cleanEmail=String(email||'').trim().toLowerCase();if(cleanEmail&&createLogin==='yes'){if(!/^\S+@\S+\.\S+$/.test(cleanEmail))problem('Enter a valid email address.');const hash=await bcrypt.hash('password123',12);const [u]=await conn.execute("INSERT INTO users(email,password_hash,role) VALUES(?,?,'patient')",[cleanEmail,hash]);userId=u.insertId;}const year=new Date().getFullYear(),[counter]=await conn.execute("INSERT INTO counters(name,value) SELECT 'patient_no',COALESCE(MAX(CAST(SUBSTRING_INDEX(patient_no,'-',-1) AS UNSIGNED)),0)+1 FROM patients ON DUPLICATE KEY UPDATE value=GREATEST(value+1,VALUES(value))");let [[seq]]=await conn.execute("SELECT value FROM counters WHERE name='patient_no'");const patientNo=`BKH-${year}-${String(seq.value).padStart(5,'0')}`;await conn.execute('INSERT INTO patients(patient_no,user_id,first_name,last_name,sex,date_of_birth,phone,email,status) VALUES(?,?,?,?,?,?,?,?,\'active\')',[patientNo,userId,firstName.trim().slice(0,80),lastName.trim().slice(0,80),sex,dateOfBirth,phone.trim().slice(0,40),cleanEmail||null]);await conn.commit();}catch(e){await conn.rollback();if(e.code==='ER_DUP_ENTRY')problem('That email or patient number is already registered.',409);throw e;}finally{conn.release();}await audit(req,'create','patient',null,`email=${String(email||'').slice(0,190)}`);return 'Patient registered.';});
post('/reception/appointments','receptionist','/reception/appointments',async(req,res)=>{const {patientId,doctorId,date,time,reason}=req.body;if(!ok(patientId))problem('Choose a patient.');await assertSlot(db,doctorId,date,time);try{await db.execute("INSERT INTO appointments(patient_id,doctor_id,appt_date,slot_time,status,type,reason) VALUES(?,?,?,?,'booked','walk_in',?)",[patientId,Number(doctorId),date,toTime(time),String(reason||'').slice(0,255)||null]);}catch(e){if(e.code==='ER_DUP_ENTRY')problem('That slot is already booked.',409);throw e;}await audit(req,'create','appointment',null,`walk-in patient=${patientId}`);return 'Appointment booked.';});
post('/reception/appointments/:id/check-in','receptionist','/reception/appointments',async(req,res)=>{const [r]=await db.execute("UPDATE appointments SET status='checked_in',checked_in_at=NOW(),queue_no=(SELECT next_no FROM (SELECT COALESCE(MAX(queue_no),0)+1 next_no FROM appointments WHERE appt_date=CURRENT_DATE) q) WHERE id=? AND status='booked' AND appt_date=CURRENT_DATE",[req.params.id]);if(!r.affectedRows)problem('Only today’s booked appointments can be checked in.',409);await audit(req,'check_in','appointment',req.params.id);return 'Patient checked in.';});
post('/reception/appointments/:id/cancel','receptionist','/reception/appointments',async(req,res)=>{const [r]=await db.execute("UPDATE appointments SET status='cancelled',cancelled_at=NOW(),cancel_reason='Cancelled by reception' WHERE id=? AND status='booked' AND appt_date>=CURRENT_DATE",[req.params.id]);if(!r.affectedRows)problem('Appointment cannot be cancelled.',409);await audit(req,'cancel','appointment',req.params.id);return 'Appointment cancelled.';});

get(['/doctor','/doctor/consultations','/doctor/labs','/doctor/prescriptions'],'doctor',async(req,res)=>{
  const [appointments]=await db.execute("SELECT a.id,a.appt_date,a.slot_time,a.status,a.patient_id,p.patient_no,CONCAT(p.first_name,' ',p.last_name) patient FROM appointments a JOIN patients p ON p.id=a.patient_id WHERE a.doctor_id=? AND a.appt_date>=CURRENT_DATE AND a.status IN('booked','checked_in','in_consultation') ORDER BY a.appt_date,a.slot_time LIMIT 100",[req.user.id]);
  const [[todayCount]]=await db.execute("SELECT COUNT(*) count FROM appointments WHERE doctor_id=? AND appt_date=CURRENT_DATE AND status IN('booked','checked_in','in_consultation')",[req.user.id]);
  const [visits]=await db.execute("SELECT v.id,v.visit_date,p.patient_no,CONCAT(p.first_name,' ',p.last_name) patient,c.status FROM visits v JOIN patients p ON p.id=v.patient_id LEFT JOIN consultations c ON c.visit_id=v.id WHERE v.doctor_id=? ORDER BY v.visit_date DESC LIMIT 50",[req.user.id]);
  const [labTests]=await db.execute("SELECT id,name FROM lab_tests WHERE active=TRUE ORDER BY name");const [drugs]=await db.execute("SELECT id,name,strength FROM drugs WHERE active=TRUE ORDER BY name");const [diagnoses]=await db.execute('SELECT id,name FROM diagnoses WHERE active=TRUE ORDER BY name');
  const checked=appointments.filter(a=>a.status==='checked_in');
  page(req,res,{title:'Doctor workspace',intro:'Review your queue, document visits, and coordinate lab and medication orders.',stats:[['Today’s queue',todayCount.count],['Checked in',checked.length],['Recent visits',visits.length]],nav:[['/doctor','Overview'],['/about','About']],forms:[{title:'Start a consultation',action:'/doctor/consultations',submit:'Open visit',fields:[field('appointmentId','Checked-in appointment','select',true,checked.map(a=>[a.id,`${a.patient_no} · ${a.patient} · ${a.slot_time}`]))]},{title:'Save or finalize consultation',action:'/doctor/consultations/save',submit:'Save consultation',fields:[field('visitId','Visit','number'),field('chiefComplaint','Chief complaint'),field('history','History','textarea',false),field('bp','Blood pressure'),field('temperature','Temperature °C','number',false),field('pulse','Pulse','number',false),field('respiratoryRate','Respiratory rate','number',false),field('spo2','SpO₂','number',false),field('weight','Weight kg','number',false),field('height','Height cm','number',false),field('diagnosisId','Diagnosis','select',false,diagnoses.map(d=>[d.id,d.name]),{empty:'Select diagnosis'}),field('diagnosisNote','Diagnosis / assessment','textarea',false),field('examination','Examination','textarea',false),field('treatmentPlan','Treatment plan','textarea',false),field('followUpDate','Follow-up date','date',false),field('finalize','Finalize now','checkbox',false,null,{value:'yes'})]},{title:'Order a laboratory test',action:'/doctor/labs',submit:'Order test',fields:[field('visitId','Visit ID','number'),field('testId','Test','select',true,labTests.map(t=>[t.id,t.name])),field('priority','Priority','select',true,[['routine','Routine'],['urgent','Urgent']]),field('note','Clinical note','textarea',false)]},{title:'Create a prescription',action:'/doctor/prescriptions',submit:'Save prescription',fields:[field('visitId','Visit','number'),field('drugId','Drug','select',true,drugs.map(d=>[d.id,`${d.name} ${d.strength}`])),field('dose','Dose'),field('frequency','Frequency'),field('duration','Duration'),field('quantity','Quantity','number')]}],tables:[table('Upcoming appointments',['Date','Time','Hospital no.','Patient','Status','Action'],appointments.map(a=>({...a,action:a.status==='checked_in'?{label:'Start visit',url:'/doctor/consultations',method:'post',extra:[['appointmentId',a.id]]}:null}))),table('Recent visits',['Visit','Date','Hospital no.','Patient','Consultation'],visits)]});
});
post('/doctor/consultations','doctor','/doctor/consultations',async(req,res)=>{const id=req.body.appointmentId;if(!ok(id))problem('Choose an appointment.');const conn=await db.getConnection();try{await conn.beginTransaction();const [[a]]=await conn.execute("SELECT * FROM appointments WHERE id=? AND doctor_id=? AND status='checked_in' FOR UPDATE",[id,req.user.id]);if(!a)problem('Appointment is not checked in or does not belong to you.',409);const [v]=await conn.execute('INSERT INTO visits(appointment_id,patient_id,doctor_id) VALUES(?,?,?)',[a.id,a.patient_id,req.user.id]);await conn.execute("INSERT INTO consultations(visit_id) VALUES(?)",[v.insertId]);await conn.execute("UPDATE appointments SET status='in_consultation' WHERE id=?",[a.id]);await conn.commit();}catch(e){await conn.rollback();if(e.code==='ER_DUP_ENTRY')problem('A visit already exists for this appointment.',409);throw e;}finally{conn.release();}await audit(req,'create','visit',null,`appointment=${id}`);return 'Visit opened. Use its ID from Recent visits to document it.';});
post('/doctor/consultations/save','doctor','/doctor/consultations',async(req,res)=>{const {visitId,chiefComplaint,history,bp,temperature,pulse,respiratoryRate,spo2,weight,height,diagnosisId,diagnosisNote,examination,treatmentPlan,followUpDate,finalize}=req.body;if(!ok(visitId)||!String(chiefComplaint||'').trim())problem('Enter a visit ID and chief complaint.');if(followUpDate&&!validDate(followUpDate))problem('Enter a valid follow-up date.');const [[v]]=await db.execute('SELECT v.id,v.appointment_id,c.status FROM visits v LEFT JOIN consultations c ON c.visit_id=v.id WHERE v.id=? AND v.doctor_id=?',[visitId,req.user.id]);if(!v)problem('Visit not found.',404);if(v.status==='finalized')problem('Finalized consultations are read-only.',409);const status=finalize==='yes'?'finalized':'draft';await db.execute(`UPDATE consultations SET chief_complaint_enc=?,history_enc=?,bp=?,temperature=?,pulse=?,respiratory_rate=?,spo2=?,weight_kg=?,height_cm=?,diagnosis_id=?,diagnosis_note_enc=?,examination_enc=?,treatment_plan_enc=?,follow_up_date=?,status=?,finalized_at=${status==='finalized'?'NOW()':'NULL'} WHERE visit_id=?`,[crypto.encrypt(chiefComplaint),crypto.encrypt(history),String(bp||'').slice(0,20)||null,temperature||null,pulse||null,respiratoryRate||null,spo2||null,weight||null,height||null,ok(diagnosisId)?diagnosisId:null,crypto.encrypt(diagnosisNote),crypto.encrypt(examination),crypto.encrypt(treatmentPlan),followUpDate||null,status,visitId]);if(status==='finalized'&&v.appointment_id)await db.execute("UPDATE appointments SET status='completed' WHERE id=? AND status='in_consultation'",[v.appointment_id]);await audit(req,status==='finalized'?'finalize':'update','consultation',visitId);return status==='finalized'?'Consultation finalized.':'Consultation saved as draft.';});
post('/doctor/labs','doctor','/doctor/labs',async(req,res)=>{const {visitId,testId,priority,note}=req.body;if(!ok(visitId)||!ok(testId)||!['routine','urgent'].includes(priority))problem('Choose a visit, test, and priority.');const [[v]]=await db.execute('SELECT id FROM visits WHERE id=? AND doctor_id=?',[visitId,req.user.id]);if(!v)problem('Visit not found.',404);const [r]=await db.execute('INSERT INTO lab_requests(visit_id,test_id,ordered_by,note_enc,priority) SELECT ?,id,?,?,? FROM lab_tests WHERE id=? AND active=TRUE',[visitId,req.user.id,crypto.encrypt(note),priority,testId]);if(!r.affectedRows)problem('Test not found or inactive.',404);await audit(req,'order','lab_request',r.insertId);return 'Lab test ordered.';});
post('/doctor/prescriptions','doctor','/doctor/prescriptions',async(req,res)=>{const {visitId,drugId,dose,frequency,duration,quantity}=req.body;if(!ok(visitId)||!ok(drugId)||!ok(quantity)||!dose?.trim()||!frequency?.trim()||!duration?.trim())problem('Complete all prescription fields with a positive quantity.');const conn=await db.getConnection();try{await conn.beginTransaction();const [[v]]=await conn.execute('SELECT id FROM visits WHERE id=? AND doctor_id=?',[visitId,req.user.id]);if(!v)problem('Visit not found.',404);let [[rx]]=await conn.execute("SELECT id FROM prescriptions WHERE visit_id=? AND doctor_id=? AND status IN('open','partial') FOR UPDATE",[visitId,req.user.id]);if(!rx){const [r]=await conn.execute("INSERT INTO prescriptions(visit_id,doctor_id,status) VALUES(?,?,'open')",[visitId,req.user.id]);rx={id:r.insertId};}const [added]=await conn.execute('INSERT INTO prescription_items(prescription_id,drug_id,dose,frequency,duration,quantity) SELECT ?,id,?,?,?,? FROM drugs WHERE id=? AND active=TRUE',[rx.id,dose.trim().slice(0,120),frequency.trim().slice(0,120),duration.trim().slice(0,120),quantity,drugId]);if(!added.affectedRows)problem('Drug not found or inactive.',404);await conn.commit();}catch(e){await conn.rollback();throw e;}finally{conn.release();}await audit(req,'create','prescription',null,`visit=${visitId}`);return 'Prescription item saved.';});

get(['/lab','/lab/requests'],'lab_technician',async(req,res)=>{const [items]=await db.execute("SELECT r.id,r.status,r.priority,r.requested_at,t.name test,p.patient_no,CONCAT(p.first_name,' ',p.last_name) patient FROM lab_requests r JOIN visits v ON v.id=r.visit_id JOIN patients p ON p.id=v.patient_id JOIN lab_tests t ON t.id=r.test_id WHERE r.status<>'cancelled' ORDER BY FIELD(r.status,'requested','sample_collected','resulted','released'),r.priority DESC,r.requested_at LIMIT 150");page(req,res,{title:'Laboratory',intro:'Track requests through collection, result entry, and release to the patient.',stats:[['Open requests',items.filter(i=>i.status!=='released').length],['Awaiting collection',items.filter(i=>i.status==='requested').length],['Awaiting release',items.filter(i=>i.status==='resulted').length]],nav:[['/lab','Overview'],['/about','About']],forms:[{title:'Update a lab request',action:'/lab/update',submit:'Save update',fields:[field('requestId','Request ID','number'),field('action','Action','select',true,[['collect','Collect sample'],['result','Enter result'],['release','Release result']]),field('resultValue','Numeric result','number',false),field('resultText','Text result','textarea',false)]}],tables:[table('Laboratory worklist',['Request','Patient no.','Patient','Test','Priority','Requested','Status'],items)]});});
post('/lab/update','lab_technician','/lab/requests',async(req,res)=>{const {requestId,action,resultValue,resultText}=req.body;if(!ok(requestId))problem('Enter a request ID.');const [[r]]=await db.execute('SELECT * FROM lab_requests WHERE id=?',[requestId]);if(!r)problem('Lab request not found.',404);if(action==='collect'&&r.status==='requested'){await db.execute("UPDATE lab_requests SET status='sample_collected',collected_at=NOW() WHERE id=? AND status='requested'",[requestId]);}else if(action==='result'&&r.status==='sample_collected'){if((resultValue===''||resultValue==null)&&!String(resultText||'').trim())problem('Enter a numeric or text result.');const [[test]]=await db.execute('SELECT reference_low,reference_high FROM lab_tests WHERE id=?',[r.test_id]);if(resultValue!==''&&resultValue!=null&&!Number.isFinite(Number(resultValue)))problem('Numeric result must be a valid number.');const flag=resultValue!==''&&resultValue!=null?engine.lab.flag(resultValue,test.reference_low,test.reference_high):null;await db.execute("UPDATE lab_requests SET status='resulted',resulted_at=NOW(),result_value=?,result_text_enc=?,flag=? WHERE id=? AND status='sample_collected'",[resultValue===''||resultValue==null?null:Number(resultValue),crypto.encrypt(resultText),flag,requestId]);}else if(action==='release'&&r.status==='resulted'){await db.execute("UPDATE lab_requests SET status='released',released_at=NOW() WHERE id=? AND status='resulted'",[requestId]);}else problem('That action is not allowed for this request status.',409);await audit(req,action,'lab_request',requestId);return 'Lab request updated.';});

get(['/pharmacy','/pharmacy/dispensing','/pharmacy/stock'],'pharmacist',async(req,res)=>{const [items]=await db.execute("SELECT pi.id item_id,pi.quantity,pi.dose,pi.frequency,pi.duration,rx.id prescription_id,p.patient_no,CONCAT(p.first_name,' ',p.last_name) patient,d.name drug,d.strength,COALESCE(SUM(ds.quantity),0) dispensed FROM prescription_items pi JOIN prescriptions rx ON rx.id=pi.prescription_id JOIN visits v ON v.id=rx.visit_id JOIN patients p ON p.id=v.patient_id JOIN drugs d ON d.id=pi.drug_id LEFT JOIN dispensings ds ON ds.prescription_item_id=pi.id WHERE rx.status IN('open','partial') GROUP BY pi.id ORDER BY rx.created_at,pi.id");const [drugs]=await db.execute("SELECT id,name FROM drugs WHERE active=TRUE ORDER BY name");const [stock]=await db.execute('SELECT d.name,b.batch_no,b.expires_on,b.qty_remaining FROM drug_batches b JOIN drugs d ON d.id=b.drug_id WHERE b.expires_on>=CURRENT_DATE ORDER BY d.name,b.expires_on LIMIT 100');page(req,res,{title:'Pharmacy',intro:'Dispense prescribed medicines, track remaining quantities, and record incoming stock batches.',stats:[['Prescription items',items.length],['Awaiting dispensing',items.filter(i=>i.quantity>i.dispensed).length],['Stock batches',stock.length]],nav:[['/pharmacy','Overview'],['/about','About']],forms:[{title:'Dispense prescription item',action:'/pharmacy/dispense',submit:'Dispense',fields:[field('itemId','Prescription item ID','number'),field('quantity','Quantity to dispense','number')]},{title:'Receive a stock batch',action:'/pharmacy/stock',submit:'Add stock batch',fields:[field('drugId','Drug','select',true,drugs.map(d=>[d.id,d.name])),field('batchNo','Batch number'),field('expiresOn','Expiry date','date'),field('quantity','Quantity','number'),field('cost','Unit cost','number')]}],tables:[table('Open prescriptions',['Item','Prescription','Patient no.','Patient','Drug','Dose','Directions','Qty','Dispensed','Remaining'],items.map(i=>({...i,directions:`${i.frequency} · ${i.duration}`,remaining:i.quantity-i.dispensed}))),table('Available stock',['Drug','Batch','Expires','Quantity'],stock)]});});
post('/pharmacy/dispense','pharmacist','/pharmacy/dispensing',async(req,res)=>{const {itemId,quantity}=req.body;if(!ok(itemId)||!ok(quantity))problem('Enter a valid prescription item and positive quantity.');const qty=Number(quantity),conn=await db.getConnection();try{await conn.beginTransaction();const [[item]]=await conn.execute("SELECT pi.*,rx.id rx_id,rx.status rx_status,d.unit_price FROM prescription_items pi JOIN prescriptions rx ON rx.id=pi.prescription_id JOIN drugs d ON d.id=pi.drug_id WHERE pi.id=? FOR UPDATE",[itemId]);if(!item||!['open','partial'].includes(item.rx_status))problem('Prescription item is not open.',409);const [[sum]]=await conn.execute('SELECT COALESCE(SUM(quantity),0) dispensed FROM dispensings WHERE prescription_item_id=?',[itemId]);if(qty>item.quantity-sum.dispensed)problem('Quantity is greater than the remaining prescription.',409);const picks=await engine.pharmacy.dispense(conn,item.drug_id,qty);for(const pick of picks)await conn.execute('INSERT INTO dispensings(prescription_item_id,pharmacist_id,quantity) VALUES(?,?,?)',[itemId,req.user.id,pick.quantity]);const [[remaining]]=await conn.execute('SELECT COUNT(*) pending FROM prescription_items pi LEFT JOIN (SELECT prescription_item_id,SUM(quantity) total FROM dispensings GROUP BY prescription_item_id) d ON d.prescription_item_id=pi.id WHERE pi.prescription_id=? AND COALESCE(d.total,0)<pi.quantity',[item.rx_id]);await conn.execute("UPDATE prescriptions SET status=? WHERE id=?",[remaining.pending?'partial':'dispensed',item.rx_id]);await conn.commit();}catch(e){await conn.rollback();throw e;}finally{conn.release();}await audit(req,'dispense','prescription_item',itemId,`quantity=${qty}`);return 'Medicine dispensed and stock updated.';});
post('/pharmacy/stock','pharmacist','/pharmacy/stock',async(req,res)=>{const {drugId,batchNo,expiresOn,quantity,cost}=req.body;if(!ok(drugId)||!batchNo?.trim()||!validDate(expiresOn)||!ok(quantity)||!Number.isFinite(Number(cost))||Number(cost)<0)problem('Enter a drug, batch, valid expiry, positive quantity, and non-negative cost.');const conn=await db.getConnection();try{await conn.beginTransaction();const [r]=await conn.execute('INSERT INTO drug_batches(drug_id,batch_no,expires_on,qty_remaining,cost) VALUES(?,?,?,?,?)',[drugId,batchNo.trim().slice(0,80),expiresOn,quantity,cost]);await conn.execute("INSERT INTO stock_movements(batch_id,qty_delta,reason,actor_id) VALUES(?,?,'stock received',?)",[r.insertId,quantity,req.user.id]);await conn.commit();}catch(e){await conn.rollback();if(e.code==='ER_DUP_ENTRY')problem('That batch number already exists for this drug.',409);throw e;}finally{conn.release();}await audit(req,'receive_stock','drug_batch',null,`drug=${drugId}`);return 'Stock batch received.';});

get(['/cashier','/cashier/invoices','/cashier/payments'],'cashier',async(req,res)=>{const [visits]=await db.execute("SELECT v.id,p.patient_no,CONCAT(p.first_name,' ',p.last_name) patient,v.visit_date FROM visits v JOIN patients p ON p.id=v.patient_id LEFT JOIN invoices i ON i.visit_id=v.id WHERE i.id IS NULL ORDER BY v.visit_date DESC LIMIT 100");const [invoices]=await db.execute("SELECT i.id,i.invoice_no,i.status,p.patient_no,CONCAT(p.first_name,' ',p.last_name) patient,COALESCE(SUM(CASE WHEN ii.voided=0 THEN ii.amount ELSE 0 END),0) total,COALESCE(pay.paid,0) paid FROM invoices i JOIN visits v ON v.id=i.visit_id JOIN patients p ON p.id=v.patient_id LEFT JOIN invoice_items ii ON ii.invoice_id=i.id LEFT JOIN (SELECT invoice_id,SUM(CASE WHEN kind='payment' THEN amount ELSE -amount END) paid FROM payments GROUP BY invoice_id) pay ON pay.invoice_id=i.id GROUP BY i.id ORDER BY i.created_at DESC LIMIT 100");page(req,res,{title:'Billing desk',intro:'Create visit invoices, accept recorded payments, and review balances and receipts.',stats:[['Visits to invoice',visits.length],['Invoices',invoices.length],['Open balances',invoices.filter(i=>Number(i.paid)<Number(i.total)).length]],nav:[['/cashier','Overview'],['/about','About']],forms:[{title:'Create invoice for a visit',action:'/cashier/invoices',submit:'Create invoice',fields:[field('visitId','Visit','select',true,visits.map(v=>[v.id,`#${v.id} · ${v.patient_no} ${v.patient}`])),field('description','Charge description'),field('quantity','Quantity','number'),field('unitPrice','Unit price','number')]},{title:'Record a payment',action:'/cashier/payments',submit:'Record payment',fields:[field('invoiceId','Invoice ID','number'),field('amount','Amount','number'),field('method','Payment method','select',true,[['cash','Cash'],['pos','POS'],['bank_transfer','Bank transfer'],['adjustment','Adjustment']]),field('reference','Reference','text',false)]}],tables:[table('Invoices',['Invoice','Patient no.','Patient','Total','Paid','Balance','Status','Action'],invoices.map(i=>({...i,balance:Math.max(0,Number(i.total)-Number(i.paid)).toFixed(2),action:i.status!=='voided'&&Number(i.paid)<Number(i.total)?{label:'Pay balance',url:'/cashier/payments',method:'post',extra:[['invoiceId',i.id],['amount',(Number(i.total)-Number(i.paid)).toFixed(2)]]}:null}))) ]});});
post('/cashier/invoices','cashier','/cashier/invoices',async(req,res)=>{const {visitId,description,quantity,unitPrice}=req.body;if(!ok(visitId)||!description?.trim()||!ok(quantity)||!Number.isFinite(Number(unitPrice))||Number(unitPrice)<0)problem('Complete the visit, description, positive quantity, and price.');const amount=(Number(quantity)*Number(unitPrice)).toFixed(2),invoiceNo=`BKH-${Date.now()}-${Math.floor(Math.random()*1000)}`;const conn=await db.getConnection();try{await conn.beginTransaction();const [[v]]=await conn.execute('SELECT id FROM visits WHERE id=? FOR UPDATE',[visitId]);if(!v)problem('Visit not found.',404);const [i]=await conn.execute('INSERT INTO invoices(invoice_no,visit_id) VALUES(?,?)',[invoiceNo,visitId]);await conn.execute("INSERT INTO invoice_items(invoice_id,item_type,description,qty,unit_price,amount) VALUES(?,'other',?,?,?,?)",[i.insertId,description.trim().slice(0,255),quantity,unitPrice,amount]);await conn.commit();}catch(e){await conn.rollback();throw e;}finally{conn.release();}await audit(req,'create','invoice',null,`visit=${visitId}`);return `Invoice ${invoiceNo} created.`;});
post('/cashier/payments','cashier','/cashier/payments',async(req,res)=>{const {invoiceId,amount,method,reference}=req.body;if(!ok(invoiceId)||!Number.isFinite(Number(amount))||Number(amount)<=0||!['cash','pos','bank_transfer','adjustment'].includes(method))problem('Enter an invoice, positive payment, and valid method.');const conn=await db.getConnection();let receipt;try{await conn.beginTransaction();const [[i]]=await conn.execute("SELECT id,status FROM invoices WHERE id=? AND status<>'voided' FOR UPDATE",[invoiceId]);if(!i)problem('Invoice not found or voided.',404);const [[totals]]=await conn.execute('SELECT COALESCE(SUM(CASE WHEN voided=0 THEN amount ELSE 0 END),0) total FROM invoice_items WHERE invoice_id=?',[invoiceId]);const [[paid]]=await conn.execute("SELECT COALESCE(SUM(CASE WHEN kind='payment' THEN amount ELSE -amount END),0) total FROM payments WHERE invoice_id=?",[invoiceId]);const n=Number(amount);if(n>Number(totals.total)-Number(paid.total)+0.0001)problem('Payment is greater than the outstanding balance.',409);receipt=`RCPT-${Date.now()}-${Math.floor(Math.random()*1000)}`;await conn.execute("INSERT INTO payments(invoice_id,receipt_no,amount,method,reference,received_by) VALUES(?,?,?,?,?,?)",[invoiceId,receipt,n,method,String(reference||'').slice(0,120)||null,req.user.id]);const status=Number(paid.total)+n>=Number(totals.total)?'paid':(Number(paid.total)+n>0?'partially_paid':'open');await conn.execute('UPDATE invoices SET status=? WHERE id=?',[status,invoiceId]);await conn.commit();}catch(e){await conn.rollback();throw e;}finally{conn.release();}await audit(req,'payment','invoice',invoiceId,`receipt=${receipt}`);return `Payment recorded. Receipt ${receipt}.`;});

