get('/admin/schedules','admin',async(req,res)=>{const [doctors]=await db.execute("SELECT u.id,CONCAT(s.first_name,' ',s.last_name) name FROM users u JOIN staff_profiles s ON s.user_id=u.id WHERE u.role='doctor' AND u.status='active' ORDER BY name");const [schedules]=await db.execute("SELECT ds.id,CONCAT(sp.first_name,' ',sp.last_name) doctor,ds.weekday,ds.start_time,ds.end_time,ds.slot_minutes FROM doctor_schedules ds JOIN staff_profiles sp ON sp.user_id=ds.doctor_id ORDER BY doctor,ds.weekday");const [timeOff]=await db.execute("SELECT toff.id,CONCAT(sp.first_name,' ',sp.last_name) doctor,toff.off_date,toff.reason FROM doctor_time_off toff JOIN staff_profiles sp ON sp.user_id=toff.doctor_id WHERE toff.off_date>=CURRENT_DATE ORDER BY toff.off_date");page(req,res,{title:'Doctor schedules',intro:'Set weekly appointment hours and record upcoming doctor leave.',stats:[['Active doctors',doctors.length],['Weekly schedules',schedules.length],['Upcoming leave',timeOff.length]],nav:[['/admin','Administration'],['/admin/schedules','Schedules'],['/admin/catalogs','Catalogs'],['/about','About']],forms:[{title:'Add or update weekly schedule',action:'/admin/schedules',submit:'Save schedule',fields:[field('doctorId','Doctor','select',true,doctors.map(d=>[d.id,d.name])),field('weekday','Day','select',true,[['0','Sunday'],['1','Monday'],['2','Tuesday'],['3','Wednesday'],['4','Thursday'],['5','Friday'],['6','Saturday']]),field('startTime','Start time','time'),field('endTime','End time','time'),field('slotMinutes','Slot length (minutes)','number')]},{title:'Record doctor leave',action:'/admin/time-off',submit:'Save leave',fields:[field('doctorId','Doctor','select',true,doctors.map(d=>[d.id,d.name])),field('offDate','Date','date'),field('reason','Reason','text',false)]}],tables:[table('Weekly schedules',['ID','Doctor','Day','Start','End','Slot minutes'],schedules.map(s=>({...s,day:['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'][s.weekday],start:String(s.start_time),end:String(s.end_time)}))),table('Upcoming leave',['ID','Doctor','Date','Reason','Action'],timeOff.map(x=>({...x,date:x.off_date,action:{label:'Remove',url:`/admin/time-off/${x.id}/remove`}})))]});});
post('/admin/schedules','admin','/admin/schedules',async(req,res)=>{const {doctorId,weekday,startTime,endTime,slotMinutes}=req.body;if(!ok(doctorId)||!/^\d$/.test(String(weekday))||Number(weekday)>6||!validTime(startTime)||!validTime(endTime)||toTime(startTime)>=toTime(endTime)||!ok(slotMinutes)||Number(slotMinutes)>240)problem('Enter a valid doctor, day, time range, and slot length (1–240 minutes).');const [[doctor]]=await db.execute("SELECT id FROM users WHERE id=? AND role='doctor' AND status='active'",[doctorId]);if(!doctor)problem('Active doctor not found.',404);await db.execute('INSERT INTO doctor_schedules(doctor_id,weekday,start_time,end_time,slot_minutes) VALUES(?,?,?,?,?) ON DUPLICATE KEY UPDATE start_time=VALUES(start_time),end_time=VALUES(end_time),slot_minutes=VALUES(slot_minutes)',[doctorId,weekday,toTime(startTime),toTime(endTime),slotMinutes]);await audit(req,'update','doctor_schedule',null,`doctor=${doctorId}`);return 'Doctor schedule saved.';});
post('/admin/time-off','admin','/admin/schedules',async(req,res)=>{const {doctorId,offDate,reason}=req.body;if(!ok(doctorId)||!validDate(offDate))problem('Choose a doctor and a valid leave date.');try{const [inserted]=await db.execute('INSERT INTO doctor_time_off(doctor_id,off_date,reason) SELECT id,?,? FROM users WHERE id=? AND role=\'doctor\' AND status=\'active\'',[offDate,String(reason||'').slice(0,255)||null,doctorId]);if(!inserted.affectedRows)problem('Active doctor not found.',404);}catch(e){if(e.code==='ER_DUP_ENTRY')problem('Leave is already recorded for that date.',409);throw e;}await audit(req,'create','doctor_time_off',null,`doctor=${doctorId}`);return 'Doctor leave recorded.';});
post('/admin/time-off/:id/remove','admin','/admin/schedules',async(req,res)=>{const [r]=await db.execute('DELETE FROM doctor_time_off WHERE id=? AND off_date>=CURRENT_DATE',[req.params.id]);if(!r.affectedRows)problem('Upcoming leave entry not found.',404);await audit(req,'delete','doctor_time_off',req.params.id);return 'Doctor leave removed.';});
get('/admin/catalogs','admin',async(req,res)=>{const [tests]=await db.execute('SELECT id,name,sample_type,price,active FROM lab_tests ORDER BY name');const [drugs]=await db.execute('SELECT id,name,generic_name,form,strength,unit_price,reorder_level,active FROM drugs ORDER BY name');const [services]=await db.execute('SELECT id,name,price,active FROM services ORDER BY name');const [diagnoses]=await db.execute('SELECT id,code,name,active FROM diagnoses ORDER BY name');const [specialties]=await db.execute('SELECT id,name,consultation_fee FROM specialties ORDER BY name');page(req,res,{title:'Catalog management',intro:'Review and activate or deactivate tests, medicines, services, and diagnoses.',stats:[['Lab tests',tests.length],['Drugs',drugs.length],['Services and diagnoses',services.length+diagnoses.length]],nav:[['/admin','Administration'],['/admin/schedules','Schedules'],['/admin/catalogs','Catalogs'],['/about','About']],forms:[{title:'Add a laboratory test',action:'/admin/catalog/lab-test',submit:'Add test',fields:[field('name','Test name'),field('sampleType','Sample type'),field('price','Price','number'),field('unit','Result unit','text',false),field('low','Reference low','number',false),field('high','Reference high','number',false)]},{title:'Add a drug',action:'/admin/catalog/drug',submit:'Add drug',fields:[field('name','Name'),field('genericName','Generic name'),field('form','Form'),field('strength','Strength'),field('price','Unit price','number'),field('reorderLevel','Reorder level','number')]},{title:'Add a diagnosis',action:'/admin/catalog/diagnosis',submit:'Add diagnosis',fields:[field('code','Code','text',false),field('name','Diagnosis')]},{title:'Add a billable service',action:'/admin/catalog/service',submit:'Add service',fields:[field('name','Service name'),field('price','Price','number')]},{title:'Add a specialty',action:'/admin/catalogs/specialty',submit:'Add specialty',fields:[field('name','Specialty'),field('fee','Consultation fee','number')]}],tables:[table('Laboratory tests',['ID','Name','Sample','Price','Active','Action'],tests.map(x=>({...x,action:{label:x.active?'Deactivate':'Activate',url:`/admin/catalogs/lab-test/${x.id}/toggle`}}))),table('Drugs',['ID','Name','Generic','Form','Strength','Price','Reorder','Active','Action'],drugs.map(x=>({...x,action:{label:x.active?'Deactivate':'Activate',url:`/admin/catalogs/drug/${x.id}/toggle`}}))),table('Services',['ID','Service','Price','Active','Action'],services.map(x=>({...x,action:{label:x.active?'Deactivate':'Activate',url:`/admin/catalogs/service/${x.id}/toggle`}}))),table('Diagnoses',['ID','Code','Diagnosis','Active','Action'],diagnoses.map(x=>({...x,action:{label:x.active?'Deactivate':'Activate',url:`/admin/catalogs/diagnosis/${x.id}/toggle`}}))),table('Specialties',['ID','Name','Fee'],specialties)]});});
post('/admin/catalogs/specialty','admin','/admin/catalogs',async(req,res)=>{if(!req.body.name?.trim()||!Number.isFinite(Number(req.body.fee))||Number(req.body.fee)<0)problem('Enter a specialty name and valid fee.');await db.execute('INSERT INTO specialties(name,consultation_fee) VALUES(?,?)',[req.body.name.trim().slice(0,100),req.body.fee]);await audit(req,'create','specialty');return 'Specialty added.';});
post('/admin/catalogs/:kind/:id/toggle','admin','/admin/catalogs',async(req,res)=>{if(!ok(req.params.id))problem('Invalid catalog item.');const tables={ 'lab-test':'lab_tests',drug:'drugs',service:'services',diagnosis:'diagnoses' };const tableName=tables[req.params.kind];if(!tableName)problem('Unknown catalog type.');const [r]=await db.execute(`UPDATE ${tableName} SET active=NOT active WHERE id=?`,[req.params.id]);if(!r.affectedRows)problem('Catalog item not found.',404);await audit(req,'toggle_active',req.params.kind,req.params.id);return 'Catalog item status updated.';});
post('/admin/users','admin','/admin/users',async(req,res)=>{const {email,password,role,firstName,lastName}=req.body;if(!/^\S+@\S+\.\S+$/.test(String(email||''))||String(password||'').length<10||!landing[role]||role==='patient'||!firstName?.trim()||!lastName?.trim())problem('Enter a valid email, 10+ character temporary password, role, and name.');const hash=await bcrypt.hash(password,12);const conn=await db.getConnection();try{await conn.beginTransaction();const [u]=await conn.execute('INSERT INTO users(email,password_hash,role) VALUES(?,?,?)',[email.trim().toLowerCase(),hash,role]);if(role!=='patient')await conn.execute('INSERT INTO staff_profiles(user_id,first_name,last_name) VALUES(?,?,?)',[u.insertId,firstName.trim().slice(0,80),lastName.trim().slice(0,80)]);await conn.commit();}catch(e){await conn.rollback();if(e.code==='ER_DUP_ENTRY')problem('That email already has an account.',409);throw e;}finally{conn.release();}await audit(req,'create','user',null,`role=${role}`);return 'User account created.';});
post('/admin/users/:id/toggle','admin','/admin/users',async(req,res)=>{if(!ok(req.params.id)||Number(req.params.id)===Number(req.user.id))problem('You cannot change this account.',403);const [r]=await db.execute("UPDATE users SET status=IF(status='active','inactive','active') WHERE id=?",[req.params.id]);if(!r.affectedRows)problem('User not found.',404);await audit(req,'toggle_status','user',req.params.id);return 'User status updated.';});
post('/admin/catalog/lab-test','admin','/admin/catalogs',async(req,res)=>{const {name,sampleType,price,unit,low,high}=req.body;if(!name?.trim()||!sampleType?.trim()||!Number.isFinite(Number(price))||Number(price)<0)problem('Enter test name, sample type, and a non-negative price.');await db.execute('INSERT INTO lab_tests(name,sample_type,price,unit,reference_low,reference_high) VALUES(?,?,?,?,?,?)',[name.trim().slice(0,160),sampleType.trim().slice(0,80),price,String(unit||'').slice(0,40)||null,low||null,high||null]);await audit(req,'create','lab_test');return 'Laboratory test added.';});
post('/admin/catalog/drug','admin','/admin/catalogs',async(req,res)=>{const {name,genericName,form,strength,price,reorderLevel}=req.body;if(!name?.trim()||!genericName?.trim()||!form?.trim()||!strength?.trim()||!Number.isFinite(Number(price))||Number(price)<0||!/^\d+$/.test(String(reorderLevel)))problem('Complete all drug fields with valid price and reorder level.');await db.execute('INSERT INTO drugs(name,generic_name,form,strength,unit_price,reorder_level) VALUES(?,?,?,?,?,?)',[name.trim(),genericName.trim(),form.trim(),strength.trim(),price,reorderLevel]);await audit(req,'create','drug');return 'Drug added to catalog.';});
post('/admin/catalog/diagnosis','admin','/admin/catalogs',async(req,res)=>{if(!req.body.name?.trim())problem('Enter a diagnosis name.');await db.execute('INSERT INTO diagnoses(code,name) VALUES(?,?)',[String(req.body.code||'').trim().slice(0,30)||null,req.body.name.trim().slice(0,160)]);await audit(req,'create','diagnosis');return 'Diagnosis added.';});
post('/admin/catalog/service','admin','/admin/catalogs',async(req,res)=>{if(!req.body.name?.trim()||!Number.isFinite(Number(req.body.price))||Number(req.body.price)<0)problem('Enter service name and non-negative price.');await db.execute('INSERT INTO services(name,price) VALUES(?,?)',[req.body.name.trim().slice(0,160),req.body.price]);await audit(req,'create','service');return 'Billable service added.';});
post('/admin/settings','admin','/admin/settings',async(req,res)=>{const {name,value}=req.body;if(!/^[a-zA-Z0-9_.-]{1,80}$/.test(String(name||''))||value==null||String(value).length>255)problem('Enter a valid setting name and value (up to 255 characters).');await db.execute('INSERT INTO settings(name,value) VALUES(?,?) ON DUPLICATE KEY UPDATE value=VALUES(value)',[name,String(value)]);await audit(req,'update','setting',null,name);return 'Setting saved.';});

module.exports=router;
